svg.metadata:
flowchart TB
  A["Take actor and requestId from authenticated context"]
  B["Begin one database transaction tx"]
  C["Write business data through tx; check success"]
  D["audit.log(input, tx); check success"]
  E["Commit only after both succeed; publish both together"]
  X["Any step fails: abort and roll back both"]
  A --> B
  B --> C
  C --> D
  D --> E
  C -->|"fails"| X
  D -->|"fails"| X
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class E good;
  class X stop;
